$_MODULE['<{lggooglereviews}prestashop>help_3612879708f67ddbaffef6b85b8a7721'] = 'Dans le champ \"Revues à afficher\", vous pouvez choisir le nombre de blocs à afficher simultanément dans le curseur.';
$_MODULE['<{lggooglereviews}prestashop>help_a8a22f09149459a347b30e8005ab34f4'] = '\"Rich Snippets\" est un ensemble de balises qui ne sont pas visibles par vos clients mais qui sont utilisées par les moteurs de recherche pour collecter des informations à partir de leurs avis. Si vous voulez faciliter l\'obtention de ces informations par les moteurs de recherche, cochez \"Oui\".';
$_MODULE['<{lggooglereviews}prestashop>help_dee2ff8dd3e1feec8bb332b79163a1a4'] = 'L\'option \"Afficher l\'en-tête\" permet d\'inclure au début du bloc un en-tête où vous pouvez afficher les données relatives à votre entreprise, telles que : le nom, l\'image, les évaluations et les liens vers votre profil dans Google Adresses.';
$_MODULE['<{lggooglereviews}prestashop>help_554d5ff6ac027319ca16bf76c83c6095'] = '\"Afficher l\'image d\'en-tête\" comprendra l\'image associée à votre entreprise si vous l\'avez téléchargée, et sinon, l\'icône par défaut que vous avez définie dans Google My Business';
$_MODULE['<{lggooglereviews}prestashop>help_bc1b4b599ba23e1aaeda1e0d4de99c3b'] = '\"Afficher le lien vers la page de votre entreprise sur Google My Business\" affiche un lien vers le profil de votre entreprise sur Google My Business.';
$_MODULE['<{lggooglereviews}prestashop>help_ee27a2fa1a14965f274765a67e5a8924'] = '\"Afficher le lien vers [Voir tous les avis]\" affiche un lien permettant à vos clients d\'accéder à la liste complète de vos avis sur Google My Business.';
$_MODULE['<{lggooglereviews}prestashop>help_559358899352d23a924ba8782fd364dc'] = 'Le lien \"Afficher le lien vers [Ajouter un avis]\" permet d\'inviter vos clients à laisser un avis sur votre entreprise.';
$_MODULE['<{lggooglereviews}prestashop>help_1ef8624b78f3fd5b154773974b2f2dac'] = 'Si vous avez choisi l\'option précédente, vous devez inclure l\'url d\'invitation. Dans la section \"Demande d\'avis\" de l\'aide, nous expliquons comment l\'obtenir';
