$_MODULE['<{lggooglereviews}prestashop>help_bfd47e79bf08ab639511bf993139b22e'] = 'Si vous voulez montrer la liste des derniers avis reçus, sélectionnez l\'option';
$_MODULE['<{lggooglereviews}prestashop>help_a481969fefacd2cac4651bc0cad8ace8'] = 'Indiquez si vous voulez montrer un lien vers le profil des utilisateurs qui ont laissé leurs avis';
$_MODULE['<{lggooglereviews}prestashop>help_4e7c6bc487018fc97dc555c507a10cc0'] = 'Consulter les données de votre entreprise';
$_MODULE['<{lggooglereviews}prestashop>help_367c548945a796b5e52169e33b27202b'] = 'Dans l\'onglet \"Statistiques\", vous pouvez consulter un résumé statistique des données de votre entreprise dans Google My Business';
$_MODULE['<{lggooglereviews}prestashop>help_b1e986d1a578a5ff89bedf9d5e52b012'] = 'Pour utiliser les API de Google Maps et Places, vous devez enregistrer l\'application et obtenir une clé API. Probablement, vous le savez déjà, mais nous vous expliquons comment obtenir cette clé si vous ne le savez pas. ';
$_MODULE['<{lggooglereviews}prestashop>help_929457b0d047a741db5a051fb3409dab'] = 'Comment créer votre clé API Google Maps';
$_MODULE['<{lggooglereviews}prestashop>help_9620b9481e88199f573c9800e8f2a621'] = 'Suivez les instructions ci-dessous pour créer une clé API. ';
$_MODULE['<{lggooglereviews}prestashop>help_45887556e1cc6a572c574708e1676ea6'] = 'Vous devez vous connecter avec votre compte gmail ou créer un nouveau compte gmail que vous souhaitez associer à votre clé API.';
$_MODULE['<{lggooglereviews}prestashop>help_b4c1815fa181e8d36cba075fb5ea51b8'] = 'Une fois connecté, vous devez aller dans la console Google Cloud Platform :';
$_MODULE['<{lggooglereviews}prestashop>help_6b05e59b1c6f2513ea4ec8811602146c'] = 'Dans le menu latéral de gauche, vous accédez à la section APIS et Services.';
$_MODULE['<{lggooglereviews}prestashop>help_7622adcc5af6e55d3a7667c19c13a6fb'] = 'Écrivez le nom du projet et cliquez sur le bouton \"CREER\". ';
$_MODULE['<{lggooglereviews}prestashop>help_55fd75e5be5f25af27c8e67eb2faa100'] = 'Ensuite, nous allons cliquer sur le bouton \"ENABLE APIS AND SERVICES\".';
$_MODULE['<{lggooglereviews}prestashop>help_fc45981f4bf623a93720e128bc1a1c10'] = 'Pour ce cas, sélectionnez \"API PLACES\".';
$_MODULE['<{lggooglereviews}prestashop>help_7684dbca91a174e239e2a8d062df29b1'] = 'Cliquez sur le bouton \"ACTIVER\".';
$_MODULE['<{lggooglereviews}prestashop>help_824a6c6060cae1ce4265e018736337df'] = 'Une fois l\'API créée, dans l\'onglet \"Credentials\". Là, cliquez sur le lien \"Credentials in APIs and services\". ';
$_MODULE['<{lggooglereviews}prestashop>help_04ee3b1cdc9f4b27e27ec84255924905'] = 'Copiez la clé API qui s\'affiche à l\'écran car nous en aurons besoin plus tard.';
$_MODULE['<{lggooglereviews}prestashop>help_ebc72db384475b19cabb579e57785996'] = 'Vous verrez que dans cette même fenêtre pop-up, vous avez la possibilité de \"Restreindre le mot de passe\". Cliquez sur ce lien si vous voulez que cette clé ne soit utilisée que dans un certain domaine, par exemple.';
$_MODULE['<{lggooglereviews}prestashop>help_449abc375ecc691847413fbc9d739a59'] = 'Une fois le mot de passe restreint, si vous l\'avez voulu, nous devrons entrer les informations de facturation car sinon, nous ne serons autorisés à appeler cette API qu\'une fois par jour et, sincèrement, j\'espère que votre site web a plus d\'une visite par jour. Cela ne signifie pas que nous allons être facturés puisque Google vous offre ce service gratuitement pour un grand nombre d\'appels à l\'API, nombre pour lequel une PME ne devra normalement pas payer. Si vous dépassez le nombre de vues que Google vous offre gratuitement, il est probable que l\'entreprise va très, très bien et que vous ne devriez pas avoir de problème à investir un peu dans ce domaine. Même si vous ne dépassez pas ce nombre, Google vous demande vos informations de facturation au cas où cela se produirait à un moment donné. D\'autre part, pour votre tranquillité d\'esprit, je vous indique que Google vous permet de mettre une limite aux appels à son API par mois. Vous pouvez donc limiter le nombre d\'appels gratuits par mois et, ainsi, vous ne serez jamais facturé ; simplement, les avis seront arrêtés si vous dépassez ce nombre.';
$_MODULE['<{lggooglereviews}prestashop>help_fb9ad09694f5986566d455aca68450a9'] = 'Comment saisir les informations de facturation ?';
$_MODULE['<{lggooglereviews}prestashop>help_719545827e174b52f5007290935e39e1'] = 'Suivez les instructions ci-dessous pour entrer vos informations de facturation.';
$_MODULE['<{lggooglereviews}prestashop>help_78a42223fc0bf73ebd95dea4c186874f'] = 'Dans la console Google Cloud Platform, si nous cliquons sur l\'icône de menu avec 3 lignes horizontales, qui se trouve à l\'extrême gauche, le menu de navigation apparaîtra. Là, nous devons cliquer sur l\'item \"Billing\". ';
$_MODULE['<{lggooglereviews}prestashop>help_17bdf9283a5ae0b5df854db1dd3dd7c9'] = 'Nous allons cliquer sur le bouton \"Gérer les comptes de facturation\".';
$_MODULE['<{lggooglereviews}prestashop>help_d854108423e34b73cf5b3537c4e74e69'] = 'Nous cliquerons sur le bouton \"Ajouter un compte de facturation\" et nous suivrons les étapes indiquées par Google, en entrant les informations demandées.';
$_MODULE['<{lggooglereviews}prestashop>help_b04a7d3f4f74a068e64d49e24b110c76'] = 'Sélectionnez le profil de paiements Google qui sera associé à ce compte de facturation. Vous pouvez sélectionner un profil existant ou en créer un nouveau.';
$_MODULE['<{lggooglereviews}prestashop>help_a800cf67d7ea062c818c5e9ee0f661a2'] = 'Enfin, dans le projet que vous êtes en train de configurer, nous devons activer la facturation pour ce projet. Nous le ferons dans \"Billing\", en cliquant sur \"Link billing account\". Nous allons sélectionner le compte et cliquer sur \"Etablir le compte\". ';
